// 3. Parse the string into a real JSON Object
const aiData = JSON.parse(cleanText);

// 4. Output 5 separate items (one for each query)
// We also pass along the 'category' and 'brief' so you can use them later!
return aiData.queries.map(q => {
  return {
    json: {
      query: q,
      category: aiData.category,
