    }
  }
});

// CONFIGURATION
const MIN_DURATION_MINUTES = 15; // minimum duration in minutes
const BANNED_KEYWORDS = [
  "reacts",
  "reaction",
  "reacting",
  "reacted",
  "trailer",
  "teaser",
  "short",
  "gameplay",
  "top 10",
  "must watch",
  "easiest"
];

// Helpers
function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// ISO-8601 duration parser: PT#H#M#S
function parseIsoDurationToMinutes(durationRaw = "PT0S") {
  const m = durationRaw.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  const hours = parseInt(m?.[1] || "0", 10);
  const minutes = parseInt(m?.[2] || "0", 10);
  const seconds = parseInt(m?.[3] || "0", 10);
  return hours * 60 + minutes + seconds / 60;
}

// Exact matching:
// - Single words: whole-word boundary match (react != reaction)
// - Phrases (contain space): match as whole phrase with boundaries around it (top 10 != top 100)
function hasBannedKeyword(text, bannedList) {
  return bannedList.some((kw) => {
    const escaped = escapeRegex(kw.trim().toLowerCase());

    // if it's a phrase (contains whitespace), match phrase with boundaries at ends
    if (/\s/.test(kw)) {
      // boundaries: start/end or non-word chars around the phrase
      // also allow spaces inside phrase exactly
      const re = new RegExp(`(^|[^\\w])${escaped}([^\\w]|$)`, "i");
      return re.test(text);
    }

    // single word: whole word only
    const re = new RegExp(`\\b${escaped}\\b`, "i");
    return re.test(text);
  });
}

return items.filter((item) => {
  const videoData = item.json.items?.[0] || {};
  const snippet = videoData.snippet || {};
  const content = videoData.contentDetails || {};

  // 1) DURATION CHECK
  const durationRaw = content.duration || "PT0S";
  const totalMinutes = parseIsoDurationToMinutes(durationRaw);

  if (totalMinutes < MIN_DURATION_MINUTES) return false;

  // 2) KEYWORD CHECK (Title & Tags)
  const title = snippet.title || "";
  const tags = Array.isArray(snippet.tags) ? snippet.tags.join(" ") : "";

  // Normalize text: lowercase + collapse whitespace
  const textToCheck = (title + " " + tags)
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();

  if (hasBannedKeyword(textToCheck, BANNED_KEYWORDS)) return false;

  return true;
});

// Ambil teks JSON dari output Gemini
const rawText = $input.first().json.text
// Bersihkan teks jika Gemini menyertakan markdown ```json ... ```
const cleanJson = rawText.replace(/```json|```/g, "").trim();

// Ubah teks menjadi objek JavaScript
const data = JSON.parse(cleanJson);

// Pecah menjadi item individu untuk n8n
