// n8n Code node - "Run once for all items"
// Parses Gemini JSON, then selects Top-3 per query with bucket diversity and global URL dedupe.

const j = $input.first().json.text;

const rawText =
  $input.first().json.text ??
  j?.content?.parts?.[0]?.text ??
  j?.content?.[0]?.text ??
  j?.text ??
  "";

if (!rawText) throw new Error("No Gemini text found (expected content.parts[0].text).");

// Strip code fences if they appear
let cleaned = String(rawText)
  .trim()
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

function canonicalizeUrl(url) {
  try {
    const u = new URL(String(url));
    const drop = new Set(["utm_source","utm_medium","utm_campaign","utm_term","utm_content","ref","fbclid","gclid","igshid"]);
    [...u.searchParams.keys()].forEach(k => { if (drop.has(k.toLowerCase())) u.searchParams.delete(k); });
    u.hash = "";
    u.protocol = "https:";
    u.hostname = u.hostname.replace(/^www\./i, "");
    u.pathname = u.pathname.replace(/\/+$/, "");
    return u.toString();
  } catch {
    return String(url ?? "");
  }
}

function parseJsonLoose(text) {
  try {
    const p = JSON.parse(text);
    return typeof p === "string" ? JSON.parse(p) : p;
  } catch (e1) {
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");
    if (start !== -1 && end !== -1 && end > start) {
      const chunk = text.slice(start, end + 1)
        .replace(/\\n/g, "\n")
        .replace(/\\"/g, '"')
        .replace(/\\\\/g, "\\");
      const p = JSON.parse(chunk);
      return typeof p === "string" ? JSON.parse(p) : p;
    }
    throw new Error("Failed to parse Gemini JSON. First 300 chars: " + text.slice(0, 300));
  }
}

const parsed = parseJsonLoose(cleaned);
const topics = Array.isArray(parsed?.results_by_topic) ? parsed.results_by_topic : [];

const TOP_PER_QUERY = 3;

const usedUrls = new Set();
const out = [];

for (const topic of topics) {
  const queryName = topic?.topic_query ?? topic?.search_term ?? topic?.query ?? "UNKNOWN_QUERY";

  const sources =
    (Array.isArray(topic?.ranked_sources) && topic.ranked_sources) ||
    (Array.isArray(topic?.selected_sources) && topic.selected_sources) ||
    (Array.isArray(topic?.selected_videos) && topic.selected_videos) ||
    (Array.isArray(topic?.results) && topic.results) ||
    [];

  // Normalize and sort by weighted_score desc
  const norm = sources.map(s => {
    const url = canonicalizeUrl(s?.url ?? s?.Website_url ?? s?.WebsiteUrl ?? s?.source_id ?? "");
    const title = s?.title ?? "No Title";
    const bucket = String(s?.bucket ?? "N/A");
    const quality_score = Number(s?.quality_score ?? s?.qualityScore ?? 0) || 0;
    const confidence = Number(s?.confidence ?? 0) || 0;
    const score = Number(s?.weighted_score ?? s?.weightedScore ?? s?.score ?? 0) || 0;
    const reason = s?.reason ?? "";
    return { url, title, bucket, quality_score, confidence, score, reason };
  }).filter(s => s.url);

  norm.sort((a,b) => b.score - a.score);

  const selected = [];
  const usedBuckets = new Set();

  // Pass 1: prefer new buckets + unused URLs
  for (const s of norm) {
    if (selected.length >= TOP_PER_QUERY) break;
    const key = s.url;
    if (usedUrls.has(key)) continue;
    if (usedBuckets.has(s.bucket)) continue;
    selected.push(s);
    usedUrls.add(key);
    usedBuckets.add(s.bucket);
  }

  // Pass 2: fill remaining with unused URLs
  for (const s of norm) {
    if (selected.length >= TOP_PER_QUERY) break;
    const key = s.url;
    if (usedUrls.has(key)) continue;
    selected.push(s);
    usedUrls.add(key);
  }

  // Pass 3: if still short, allow duplicates across queries (avoid duplicates inside this query)
  for (const s of norm) {
    if (selected.length >= TOP_PER_QUERY) break;
    const key = s.url;
    if (selected.some(x => x.url === key)) continue;
    selected.push(s);
  }

  selected.forEach((s, i) => {
    out.push({
      json: {
        idx: `${queryName}#${String(i+1).padStart(2,"0")}`,
        title: s.title,
        url: s.url,
        url_canonical: s.url,
        score: s.score,
        bucket: s.bucket,
        quality_score: s.quality_score,
        confidence: s.confidence,
        reason: s.reason,
        search_term: queryName,
      }
    });
  });
}

return out;

// n8n Code node (Run once for all items)
// Select Top 3 videos per search_term/topic_query with global videoId dedupe.

const first = $input.first().json.text;

const rawText = $input.first().json.text ??
  first?.content?.parts?.[0]?.text ??
  first?.content?.[0]?.text ??
  first?.text ??
  first?.content ??
  "";

if (!rawText) {
  throw new Error("No Gemini text found. Check path: content.parts[0].text");
}

// Strip code fences
const cleaned = String(rawText)
  .trim()
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
  if (typeof parsed === "string") parsed = JSON.parse(parsed);
} catch (e) {
  throw new Error("Failed to parse Gemini JSON. First 300 chars: " + cleaned.slice(0, 300));
}

const TOP_PER_SEARCH = 3;

// Collect videos grouped by topic_query
let rows = [];

if (Array.isArray(parsed?.results_by_topic)) {
  for (const t of parsed.results_by_topic) {
    const group = t?.topic_query ?? t?.search_term ?? t?.query ?? "UNKNOWN_QUERY";
    const videos =
      (Array.isArray(t?.rated_videos) && t.rated_videos) ||
      (Array.isArray(t?.ranked_videos) && t.ranked_videos) ||
      (Array.isArray(t?.selected_videos) && t.selected_videos) ||
      [];
    for (const v of videos) rows.push({ ...v, _group: group });
  }
} else {
  const rated = parsed?.rated_videos ?? parsed?.results ?? parsed?.items ?? [];
  for (const v of rated) {
    const group = v?.search_term ?? v?.topic_query ?? v?.query ?? "UNKNOWN_QUERY";
    rows.push({ ...v, _group: group });
  }
}

// Group by search term
const groups = new Map();
for (const v of rows) {
  const g = String(v._group || "UNKNOWN_QUERY");
  if (!groups.has(g)) groups.set(g, []);
  groups.get(g).push(v);
}

if (groups.size === 1 && groups.has("UNKNOWN_QUERY")) {
  throw new Error("All items grouped into UNKNOWN_QUERY. Gemini output lacks topic_query/search_term grouping.");
}

const usedIds = new Set();
let selected = [];

// Select top 3 per group with global dedupe
for (const [g, arr] of groups.entries()) {
  arr.sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0));
  const picked = [];

  // pass 1: unique ids
  for (const v of arr) {
    if (picked.length >= TOP_PER_SEARCH) break;
    const id = v.video_id ?? v.videoId ?? v.id ?? "";
    if (!id) continue;
    if (usedIds.has(id)) continue;
    picked.push(v);
    usedIds.add(id);
  }

  // pass 2: allow duplicates if needed
  for (const v of arr) {
    if (picked.length >= TOP_PER_SEARCH) break;
    const id = v.video_id ?? v.videoId ?? v.id ?? "";
    if (!id) continue;
    if (picked.some(x => (x.video_id ?? x.videoId ?? x.id) === id)) continue;
    picked.push(v);
  }

  picked.forEach(v => selected.push({ ...v, _group: g }));
}

// Output items
return selected.map((v, i) => ({
  json: {
    idx: String(i).padStart(5, "0"),
    video_id: v.video_id ?? v.videoId ?? v.id ?? "",
    title: v.title ?? "",
    channel: v.channel ?? "",
    score: Number(v.score) || 0,
    tag: v.tag ?? "",
    reason: v.reason ?? "",
    search_term: v._group ?? "",
  }
}));

// Attach stable videoId + channel (and other metadata) using video_id lookup (not title).

const agg = $node["Aggregate"].json;

const ids = agg.id || [];
const titles = agg.title || [];
const descriptions = agg.description || [];
const channels = agg.channel || [];
const searchTerms = agg.search_term || [];
const publishedAts = agg.publishedAt || [];
const durations = agg.duration || [];
const viewCounts = agg.viewCount || [];
const likeCounts = agg.likeCount || [];

if (!Array.isArray(ids)) throw new Error("Aggregate node must output array: id[]");

const metaById = new Map();
for (let i = 0; i < ids.length; i++) {
  const id = String(ids[i] ?? "");
  if (!id || metaById.has(id)) continue;
  metaById.set(id, {
    title: titles[i] ?? "",
    description: descriptions[i] ?? "",
    channel: channels[i] ?? "Unknown Channel",
    search_term: searchTerms[i] ?? "",
    publishedAt: publishedAts[i] ?? null,
    duration: durations[i] ?? null,
    viewCount: viewCounts[i] ?? null,
    likeCount: likeCounts[i] ?? null,
  });
}

return $input.all().map((item) => {
  const vid = String(item.json.video_id ?? item.json.videoId ?? item.json.id ?? "");
  const meta = metaById.get(vid);

  return {
    json: {
      ...item.json,
      videoId: vid || null,
      url: vid ? `https://www.youtube.com/watch?v=${vid}` : (item.json.url ?? ""),
      title: item.json.title || (meta?.title ?? ""),
      channel: item.json.channel || (meta?.channel ?? "Unknown Channel"),
      description: meta?.description ?? item.json.description ?? "",
      publishedAt: meta?.publishedAt ?? item.json.publishedAt ?? null,
      duration: meta?.duration ?? item.json.duration ?? null,
      viewCount: meta?.viewCount ?? item.json.viewCount ?? null,
      likeCount: meta?.likeCount ?? item.json.likeCount ?? null,
      search_term: item.json.search_term || meta?.search_term || "",
    }
  };
});

// Clean WebVTT/SRT-like transcripts and output a stable schema.
// Mode: Run Once for Each Item

function cleanWebVTT(text) {
  if (!text) return "";

  return String(text)
    .replace(/^\uFEFF?WEBVTT[^\n]*\n/gi, "") // Remove WEBVTT header line
    .replace(/^\s*\d+\s*$/gm, "")            // Remove cue numbers (lines that are ONLY digits)
    .replace(
      /^\s*\d{1,2}:\d{2}(?::\d{2})?\.\d{3}\s*-->\s*\d{1,2}:\d{2}(?::\d{2})?\.\d{3}.*$/gm,
      ""
    )                                       // Remove timestamp lines
    .replace(/<[^>]*>/g, "")                // Strip tags
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{2,}/g, "\n")
    .trim();
}

const input = $json || {};

const videoId = input.videoId ?? input.video_id ?? input.id ?? null;
const title = input.title ?? "";
const rawTranscript =
  input.transcript ?? input.data ?? input.text ?? "";

// Hard-cap length so every transcript fits in the one LLM call that follows
// (same idea as MAX_CHARS in "Clean Content"). Raise or lower to taste.
const MAX_TRANSCRIPT_CHARS = 20000;

let cleaned = cleanWebVTT(rawTranscript);
if (cleaned.length > MAX_TRANSCRIPT_CHARS) {
  cleaned = cleaned.slice(0, MAX_TRANSCRIPT_CHARS) + "\n\n[TRUNCATED]";
}

return {
  json: {
    videoId,
    video_id: input.video_id ?? videoId,  // keep both keys for downstream joins
    title,
    transcript_text: cleaned,
    transcript_ok:
      input.status ?? input.ok ?? (rawTranscript ? "ok" : "missing"),
    transcript_len: cleaned.length,
  },
};

// n8n Code node (Run once for all items)
// Combines Tavily search results across queries, preserves per-query provenance,
// canonicalizes URLs, computes deterministic scores, and prefilters top-N per query.

const PREFILTER_PER_QUERY = 12; // keep this many per search term for LLM judging
const MIN_WORD_LEN = 3;

function canonicalizeUrl(url) {
  try {
    const u = new URL(String(url));
    // drop common tracking params
    const drop = new Set(["utm_source","utm_medium","utm_campaign","utm_term","utm_content","ref","fbclid","gclid","igshid"]);
    [...u.searchParams.keys()].forEach(k => { if (drop.has(k.toLowerCase())) u.searchParams.delete(k); });
    u.hash = "";
    // normalize
    u.protocol = "https:";
    u.hostname = u.hostname.replace(/^www\./i, "");
    // remove trailing slash
    u.pathname = u.pathname.replace(/\/+$/, "");
    return u.toString();
  } catch {
    return String(url ?? "");
  }
}

function domainFromUrl(url) {
  try { return new URL(url).hostname.toLowerCase(); } catch { return ""; }
}

function authorityHeuristic(domain) {
  const d = (domain || "").toLowerCase();
  if (!d) return 50;
  if (/\.(gov|edu)$/.test(d)) return 95;
  if (/arxiv\.org|acm\.org|ieee\.org|nature\.com|science\.org|openai\.com|nvidia\.com|cloudflare\.com/.test(d)) return 90;
  if (/github\.com|docs\./.test(d)) return 75;
  if (/medium\.com|substack\.com/.test(d)) return 45;
  if (/reddit\.com|tiktok\.com|facebook\.com|instagram\.com/.test(d)) return 20;
  return 55;
}

function paywallRisk(url) {
  const u = (url || "").toLowerCase();
  if (/ft\.com|wsj\.com|bloomberg\.com|economist\.com/.test(u)) return 1.0;
  return 0.0;
}

function tokenize(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .split(/\s+/)
    .filter(w => w && w.length >= MIN_WORD_LEN);
}

function overlapScore(query, text) {
  const q = tokenize(query);
  const t = String(text || "").toLowerCase();
  if (!q.length) return 0;
  let hits = 0;
  for (const w of q) if (t.includes(w)) hits++;
  return Math.round((hits / q.length) * 100);
}

// 1) Flatten per-query results and preserve the originating search term
let candidates = [];

for (const item of items) {
  const results = item.json.results || [];
  const search_term = item.json.query || item.json.search_term || "";
  const query_category = item.json.category ?? null;
  const brief = item.json.brief ?? null;

  // Deduplicate within THIS query by canonical URL
  const seen = new Set();

  results.forEach((r, rank) => {
    const url_raw = r.url || "";
    const url = canonicalizeUrl(url_raw);
    if (!url || seen.has(url)) return;
    seen.add(url);

    const title = r.title || "";
    const snippet = r.content || "";

    const domain = domainFromUrl(url);
    const authority = authorityHeuristic(domain);
    const relevance = Math.max(
      overlapScore(search_term, title),
      Math.round(0.7 * overlapScore(search_term, title) + 0.3 * overlapScore(search_term, snippet))
    );

    // cheap proxy (real text comes later in extract step)
    const len = snippet.length;
    const lengthScore = len < 250 ? 15 : len < 1200 ? 70 : 50;

    const paywallPenalty = paywallRisk(url) * 15;

    const score_det = Math.round(
      0.30 * authority +
      0.30 * relevance +
      0.10 * lengthScore -
      paywallPenalty
    );

    candidates.push({
      title,
      url,
      content: snippet,
      search_term,
      query_category,
      brief,
      tavily_rank: rank + 1,
      domain,
      score_det,
      score_features: { authority, relevance, lengthScore, paywallPenalty }
    });
  });
}

// 2) Prefilter top-N per search term (keeps diversity across intents)
const byQuery = new Map();
for (const c of candidates) {
  const q = String(c.search_term || "UNKNOWN_QUERY");
  if (!byQuery.has(q)) byQuery.set(q, []);
  byQuery.get(q).push(c);
}

let prefiltered = [];
for (const [q, arr] of byQuery.entries()) {
  arr.sort((a,b) => (b.score_det - a.score_det) || (a.tavily_rank - b.tavily_rank));
  prefiltered.push(...arr.slice(0, PREFILTER_PER_QUERY));
}

// 3) Output one object containing all prefiltered candidates
return [{
  json: {
    candidates: prefiltered,
    brief: items[0]?.json?.brief ?? null,
    category: items[0]?.json?.category ?? null
  }
}];

// Clean + normalize extracted text, canonicalize URL, and hard-cap length to keep LLM calls stable.

function canonicalizeUrl(url) {
  try {
    const u = new URL(String(url));
    const drop = new Set(["utm_source","utm_medium","utm_campaign","utm_term","utm_content","ref","fbclid","gclid","igshid"]);
    [...u.searchParams.keys()].forEach(k => { if (drop.has(k.toLowerCase())) u.searchParams.delete(k); });
    u.hash = "";
    u.protocol = "https:";
    u.hostname = u.hostname.replace(/^www\./i, "");
    u.pathname = u.pathname.replace(/\/+$/, "");
    return u.toString();
  } catch {
    return String(url ?? "");
  }
}

const MAX_CHARS = 20000;

return $input.all().map(item => {
  const rawContent =
    (item.json.results && item.json.results[0] ? item.json.results[0].raw_content : item.json.data) ||
    "";

  const sourceUrl =
    (item.json.results && item.json.results[0] ? item.json.results[0].url : item.json.url) ||
    "";

  let text = String(rawContent || "")
    .replace(/\r/g, "")
    .replace(/\n\s*\n/g, "\n")
    .trim();

  if (text.length > MAX_CHARS) {
    text = text.slice(0, MAX_CHARS) + "\n\n[TRUNCATED]";
  }

  const url = canonicalizeUrl(sourceUrl);

  return {
    json: {
      url,
      url_canonical: url,
      clean_content: text
    }
  };
});

// 1. Get the raw text from the previous node
const rawText = $input.first().json.text || ""; 

// 2. Clean the string (remove markdown code fences if they exist)
const cleanedText = rawText.replace(/```json\n?|```/g, "").trim();

try {
  // 3. Parse the string into a real JSON array
  const dataArray = JSON.parse(cleanedText);

  // 4. Return the data as individual items for n8n to loop through
  return dataArray.map(item => ({ json: item }));
} catch (error) {
  // If parsing fails, return the error for debugging
  return [{ json: { error: "Failed to parse JSON", details: error.message, original: rawText } }];
}

// Parse JSON printed by the Python transcript script (stdout -> JSON)
const stdout = $json.stdout ?? $input.first().json.stdout ?? "";

if (!stdout) {
  return [{ json: { status: "error", transcript: "", error: "No stdout from transcript script" } }];
}

try {
  const parsed = JSON.parse(stdout);
  return [{ json: parsed }];
} catch (e) {
  // Sometimes scripts print extra lines; attempt to extract first {...} or [...] block
  const s = String(stdout);
  const firstObj = s.indexOf("{");
  const lastObj = s.lastIndexOf("}");
  const firstArr = s.indexOf("[");
  const lastArr = s.lastIndexOf("]");

  let candidate = "";
  if (firstArr !== -1 && lastArr !== -1 && lastArr > firstArr) candidate = s.slice(firstArr, lastArr + 1);
  else if (firstObj !== -1 && lastObj !== -1 && lastObj > firstObj) candidate = s.slice(firstObj, lastObj + 1);

  try {
    const parsed2 = JSON.parse(candidate);
    return [{ json: parsed2 }];
  } catch (e2) {
    return [{ json: { status: "error", transcript: "", error: "Failed to parse transcript JSON", raw_preview: s.slice(0, 400) } }];
  }
}

// 1. Extract the raw text from the AI node
const rawText = $input.first().json.text;

if (!rawText) {
  throw new Error("No data received from the AI node.");
}

// 2. Clean up the text (removes markdown backticks if the AI included them)
const cleanedText = rawText
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsedData;
try {
  parsedData = JSON.parse(cleanedText);
} catch (error) {
  throw new Error("Failed to parse AI response into JSON: " + error.message);
}

// 3. Transform the array into n8n compatible items
// This ensures each object in your JSON becomes a separate row in the n8n table
return parsedData.map(item => {
  return {
    json: {
      source_id: item.source_id,
      title: item.title,
      type: item.type,
      url: item.url,
      score: item.score,
      why_selected: item.why_selected,
